def rows(block, split):
    out = []
    for i, line in enumerate(block.strip().splitlines(), 1):
        meta, text = line.split(" | ", 1)
        parts = meta.split()
        labels = {field: mapping[value] for field, mapping, value in zip(FIELDS, ALIASES, parts[:6])}
        # Explicit final sentence in the last held-out example is an actual negative.
        if split == "test" and i == 90:
            labels["gov_contract"] = "NO"
        labels["amount_rub"] = None if parts[6] == "-" else int(parts[6])
        out.append(dict(id=f"{split}-{i:03}", text=text, labels=labels,
                        industry=parts[7], style=parts[8], source="agent-authored"))
    return out


def main():
    dest = ROOT / "dataset"
    manifest = {}
    for split, source in [("examples", EXAMPLES), ("dev", DEV), ("test", TEST)]:
        target = dest / f"{split}.jsonl"
        if target.exists():
            raise SystemExit(f"Refusing to overwrite {target}; corpus is immutable after authoring")
        data = rows(source, split)
        target.write_text("".join(json.dumps(r, ensure_ascii=False) + "\n" for r in data))
        manifest[target.name] = {"count": len(data), "sha256": hashlib.sha256(target.read_bytes()).hexdigest()}
    (dest / "human.jsonl").touch()
    (dest / "manifest.json").write_text(json.dumps(manifest, indent=2) + "\n")
    print(json.dumps(manifest, indent=2))


if __name__ == "__main__":
    main()
